private val Purple=Color(0xFF7B44EF);private val PurpleSoft=Color(0xFFF5F0FF);private val TextMain=Color(0xFF17131F);private val Muted=Color(0xFF8F8798);private val Green=Color(0xFF18B97D);private val Red=Color(0xFFE84C61);private const val AUTH_TIMEOUT_MS=45_000L
private tailrec fun Context.activity():Activity?=when(this){is Activity->this;is ContextWrapper->baseContext.activity();else->null}

private object CloudAuth{
    fun configured()=BuildConfig.FLOSI_FIREBASE_API_KEY.isNotBlank()&&BuildConfig.FLOSI_FIREBASE_APP_ID.isNotBlank()&&BuildConfig.FLOSI_FIREBASE_PROJECT_ID.isNotBlank()&&BuildConfig.FLOSI_GOOGLE_WEB_CLIENT_ID.isNotBlank()
    private suspend fun<T> timed(block:suspend()->T):T=try{withTimeout(AUTH_TIMEOUT_MS){block()}}catch(_:TimeoutCancellationException){error("AUTH_TIMEOUT")}
    fun auth(context:Context):FirebaseAuth{val app=FirebaseApp.getApps(context).firstOrNull{it.name=="flosi-auth"}?:run{check(configured()){"AUTH_CONFIG"};val options=FirebaseOptions.Builder().setApiKey(BuildConfig.FLOSI_FIREBASE_API_KEY).setApplicationId(BuildConfig.FLOSI_FIREBASE_APP_ID).setProjectId(BuildConfig.FLOSI_FIREBASE_PROJECT_ID).build();FirebaseApp.initializeApp(context.applicationContext,options,"flosi-auth")?:error("AUTH_INIT")};return FirebaseAuth.getInstance(app)}
    suspend fun google(context:Context):FirebaseUser=timed{val activity=context.activity()?:error("AUTH_ACTIVITY");val option=GetSignInWithGoogleOption.Builder(serverClientId=BuildConfig.FLOSI_GOOGLE_WEB_CLIENT_ID).build();val request=GetCredentialRequest.Builder().addCredentialOption(option).build();val credential=CredentialManager.create(activity).getCredential(activity,request).credential;require(credential is CustomCredential&&credential.type==GoogleIdTokenCredential.TYPE_GOOGLE_ID_TOKEN_CREDENTIAL){"AUTH_GOOGLE"};val token=GoogleIdTokenCredential.createFrom(credential.data).idToken;auth(activity).signInWithCredential(GoogleAuthProvider.getCredential(token,null)).await().user?:error("AUTH_SESSION")}
    suspend fun emailLogin(context:Context,email:String,password:String):FirebaseUser=timed{auth(context).signInWithEmailAndPassword(email.trim(),password).await().user?:error("AUTH_LOGIN")}
    suspend fun emailRegister(context:Context,email:String,password:String):FirebaseUser=timed{auth(context).createUserWithEmailAndPassword(email.trim(),password).await().user?:error("AUTH_REGISTER")}
    suspend fun reset(context:Context,email:String){timed{auth(context).sendPasswordResetEmail(email.trim()).await()}}
}

private data class Strength(val len:Boolean,val lower:Boolean,val upper:Boolean,val digit:Boolean,val symbol:Boolean){val strong get()=len&&lower&&upper&&digit&&symbol}
private fun strength(v:String)=Strength(v.length>=12,v.any(Char::isLowerCase),v.any(Char::isUpperCase),v.any(Char::isDigit),v.any{!it.isLetterOrDigit()&&!it.isWhitespace()})
private enum class Stage{CHOICE,EMAIL,REGISTER,RESET}

private fun txt(lang:String,ar:String,en:String,tr:String,fr:String,de:String,es:String)=when(lang){"ar"->ar;"tr"->tr;"fr"->fr;"de"->de;"es"->es;else->en}
private fun authError(code:String?,lang:String):String=when(code){
    "AUTH_TIMEOUT"->txt(lang,"لم تكتمل العملية خلال 45 ثانية. تحقق من الإنترنت وحاول مرة أخرى.","The operation did not finish within 45 seconds. Check your connection and try again.","İşlem 45 saniye içinde tamamlanmadı. İnternetini kontrol edip tekrar dene.","L’opération n’a pas abouti sous 45 secondes. Vérifiez votre connexion et réessayez.","Der Vorgang wurde nicht innerhalb von 45 Sekunden abgeschlossen. Prüfe deine Verbindung und versuche es erneut.","La operación no terminó en 45 segundos. Revisa tu conexión e inténtalo de nuevo.")
    "AUTH_CONFIG","AUTH_INIT"->txt(lang,"إعداد تسجيل الدخول غير مكتمل.","Sign-in configuration is incomplete.","Giriş yapılandırması eksik.","La configuration de connexion est incomplète.","Die Anmeldekonfiguration ist unvollständig.","La configuración de inicio de sesión está incompleta.")
    "AUTH_ACTIVITY","AUTH_GOOGLE","AUTH_SESSION"->txt(lang,"تعذر تسجيل الدخول عبر Google.","Google sign-in could not be completed.","Google ile giriş tamamlanamadı.","La connexion Google n’a pas pu être effectuée.","Google-Anmeldung konnte nicht abgeschlossen werden.","No se pudo completar el inicio de sesión con Google.")
    "AUTH_LOGIN"->txt(lang,"تعذر تسجيل الدخول.","Could not sign in.","Giriş yapılamadı.","Connexion impossible.","Anmeldung nicht möglich.","No se pudo iniciar sesión.")
    "AUTH_REGISTER"->txt(lang,"تعذر إنشاء الحساب.","Could not create account.","Hesap oluşturulamadı.","Impossible de créer le compte.","Konto konnte nicht erstellt werden.","No se pudo crear la cuenta.")
    else->txt(lang,"حدث خطأ. حاول مرة أخرى.","Something went wrong. Try again.","Bir hata oluştu. Tekrar dene.","Une erreur s’est produite. Réessayez.","Etwas ist schiefgelaufen. Versuche es erneut.","Algo salió mal. Inténtalo de nuevo.")
}

@Composable private fun BrandHeader(subtitle:String?=null){val lang=LocalFlosiLanguage.current;Image(painterResource(R.drawable.flosi_brand_mark),txt(lang,"شعار فلوسي","Flosi logo","Flosi logosu","Logo Flosi","Flosi-Logo","Logo de Flosi"),Modifier.size(104.dp));Text("Flosi",style=MaterialTheme.typography.headlineLarge,fontWeight=FontWeight.Bold,color=TextMain);subtitle?.let{Text(it,color=Muted)}}

@Composable fun FlosiAuthGate(content:@Composable()->Unit){val context=LocalContext.current;if(!CloudAuth.configured()){MissingConfig();return};val auth=remember{CloudAuth.auth(context)};var user by remember{mutableStateOf(auth.currentUser)};var stage by remember{mutableStateOf(Stage.CHOICE)};DisposableEffect(auth){val listener=FirebaseAuth.AuthStateListener{user=it.currentUser};auth.addAuthStateListener(listener);onDispose{auth.removeAuthStateListener(listener)}};if(user!=null){content();return};when(stage){Stage.CHOICE->Choice({user=it},{stage=Stage.EMAIL});Stage.EMAIL->EmailLogin({user=it},{stage=Stage.REGISTER},{stage=Stage.RESET},{stage=Stage.CHOICE});Stage.REGISTER->EmailRegister({user=it},{stage=Stage.EMAIL});Stage.RESET->ResetPassword{stage=Stage.EMAIL}}}

